const fs = require('node:fs');
const path = require('node:path');

const root = path.resolve(__dirname, '..');
const sourcePath = path.join(root, 'assets', 'user-vocabulary-examples.js');
const outputPath = path.join(root, 'assets', 'user-vocabulary-index.js');

global.window = {};
require(sourcePath);

const source = window.USER_VOCAB_EXAMPLES || {};
const index = Object.fromEntries(Object.entries(source).map(([hanzi, entry]) => [hanzi, {
    pinyin: entry.pinyin || '',
    meaning: entry.meaning || ''
}]));

const output = [
    '// Generated by tools/build-vocabulary-index.js. Keep the full examples file as the source of truth.',
    `window.USER_VOCAB_INDEX = ${JSON.stringify(index)};`,
    ''
].join('\n');

fs.writeFileSync(outputPath, output, 'utf8');
console.log(`Wrote ${Object.keys(index).length} vocabulary entries to ${path.relative(root, outputPath)}.`);
